// === Tab: March ===
class March {
	constructor(x, y, sze, st, pal, frames, timer = 0) {
		this.x = x;
		this.y = y;
		this.sze = sze;
		this.st = st; // must be same for left and right foot ~~random(2, 5); // 2, 3, 4
		this.pal = pal;
		this.frames = frames;
		this.timer = timer;
	}

	update(resetY) {
		this.timer++;
		if (this.timer >= this.frames) {
			this.timer = 0;
			this.y -= this.sze * 2;
			if (this.y < 0) this.y += resetY;
		}
	}

	show() {
		const t = frameCount / 30;
		const st = this.st;
		const f = (this.timer > this.frames / st) ? 1 : (this.timer / this.frames / st);

		for (let i = 0; i < this.pal.length; i++) {
			fill(this.pal[i]);
			const xo = (noise(this.x, i, t) - 0.5) * this.sze * 0.25;
			const yo = (noise(i, t, this.x) - 0.5) * this.sze * 0.25 + f * this.sze;
			rect(this.x + xo, this.y + yo, this.sze, this.sze, this.sze * 0.1);
		}

	} // draw

} // class March

