const FPS = 30;
let S, numX, numY, offsetYs, marchingCubes;
const palettes = [
	["rgb(255,0,0)", "rgb(0,255,0)", "rgb(0,0,255)"],
	["rgb(255,255,0)", "rgb(255,0,255)", "rgb(0,255,255)"]
]

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("pairs of blocks marching upward in synchrony, each following its own unique rhythm with chromatic divergation");
	frameRate(FPS);
	noStroke();

	S = ~~(min(width/4, height/3) / 6);
	numX = ~~(width/S/2) + 1; // allways pairs of feets
	numY = ~~(height/S) + 1; 
	offsetYs = [];
	marchingCubes = [];
	for (let i = 0; i < numX; i++) {
		const startY = ~~random(numY);
		offsetYs[i] = startY;
		const x = i * S * 2;
		const y = ~~random(numY) * S;
		var st = ~~random(2, 5); // step movement 2,3,4
		const pal = palettes[i % palettes.length];
		marchingCubes.push(new March(x, y, S, st, pal, FPS, 0));

		const dir = 1; // Math.sign(random(-1, 1))
		marchingCubes.push(new March(x+S, y+S*dir, S, st, pal, FPS, (~~(FPS/2)*dir+FPS) % FPS));
	}
}

function draw() {
	blendMode(BLEND);
	background(4, 4, 12, 64);

	blendMode(ADD);
	for (const mc of marchingCubes) {		
		mc.update(numY*S);
		mc.show();
	}
}


function mousePressed() {
	if (mouseButton != RIGHT) setup();
}
